FormulaFieldDefinitions.FormulaFieldDefinition:
local StringVar Array ptzFields := Split(PrintTimeZone,",");
local numberVar i;
local numberVar j:=1;
local stringVar ptzCorrected;

FOR i:= 1 TO Count(ptzFields) DO(
 IF(j=1 OR j=3) AND NOT (Left(TrimLeft(ptzFields[i]),1) IN ["+","-","0" TO "9"])
 THEN  ptzCorrected := ptzCorrected + ptzFields[i]
 ELSE (ptzCorrected := ptzCorrected + "," + ptzFields[i]; j := j + 1; ptzCorrected;);
);

ptzCorrected;
